mapper.select:
select pmrn.id id,pmrn.org_id orgId,pmrn.patient_id patientId,pmrn.member_type_id memberTypeId,pmrn.master_card masterCard,pmrn.card_number cardNumber, pmrn.status status,pmrn.principal_amount principalAmount,pmrn.bonus_amount bonusAmount,pmrn.point point,pmrn.last_expired_time lastExpiredTime, pmrn.next_expired_time nextExpiredTime,pmrn.remarks remarks,pmrn.inservice inservice 
from patient_member_relation pmrn
where pmrn.master_card_id =#{form.masterCardId} and pmrn.secondary_card_id =#{form.secondaryCardId} and pmrn.bind_type =#{form.bindType}
